let locale=localStorage.getItem("ai-coo-locale")==="zh"?"zh":"en",state,brief,feedbackAnalysis,dataHealth,view="command",dailyDate=null;
const t=(key)=>copy[locale][key]??copy.en[key]??key;
const pick=(object,key)=>locale==="zh"&&object?.[`${key}_zh`]?object[`${key}_zh`]:object?.[key];
const esc=(value)=>String(value??"—").replace(/[&<>"']/g,(c)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);
const fmt=(value,unit)=>value===null||value===undefined?"—":`${new Intl.NumberFormat(locale==="zh"?"zh-CN":"en",{maximumFractionDigits:2}).format(value)}${unit==="percent"?"%":""}`;
const operatingTimeZone="Asia/Shanghai";
const date=(value)=>value?new Date(value).toLocaleString(locale==="zh"?"zh-CN":"en",{dateStyle:"medium",timeStyle:"short",timeZone:operatingTimeZone}):"—";
const day=(value)=>{if(!value)return "—";const parts=Object.fromEntries(new Intl.DateTimeFormat("en-CA",{year:"numeric",month:"2-digit",day:"2-digit",timeZone:operatingTimeZone}).formatToParts(new Date(value)).map(({type,value:part})=>[type,part]));return `${parts.year}-${parts.month}-${parts.day}`;};
function latestOperatingDay(){const candidates=[state.metadata.last_updated,...state.jobs.map((item)=>item.last_run),...state.audit.map((item)=>item.at),...state.content.map((item)=>item.published_at)].filter(Boolean).map(day).filter((item)=>item!=="—");return candidates.sort().at(-1)??day(state.metadata.last_updated);}
function permanentContentUrl(item){const url=item.publish_url??item.url;return typeof url==="string"&&/^https:\/\//.test(url)?url:null;}
function publishedWithEvidence(item){return item.status==="published"&&Boolean(permanentContentUrl(item));}
function attributionCompleteness(item){const attribution=(state.attributions??[]).find((row)=>row.content_id===item.id);const steps=[permanentContentUrl(item),item.landing_url??attribution?.landing_url,item.campaign_url??attribution?.app_store_campaign_url];return{complete:steps.filter(Boolean).length,total:steps.length};}
function resultSummary(result){if(result===null||result===undefined)return "—";if(typeof result==="string")return result;if(typeof result!=="object")return String(result);return Object.entries(result).slice(0,4).map(([key,value])=>`${key.replaceAll("_"," ")} ${value??"—"}`).join(" · ")||"—";}
function channelName(id){return state.channels.find((item)=>item.id===id)?.name??id;}
function jobName(job){const names={import_app_store_analytics:["App Store analytics import","App Store 数据导入"],update_content_performance:["Content performance check","内容表现检查"],refresh_app_store_reviews:["App Store reviews refresh","App Store 评论同步"],calculate_anomalies:["Change detection","变化检测"],generate_insights:["Insight generation","洞察生成"],refresh_daily_brief:["Daily brief refresh","每日简报更新"],evaluate_experiments:["Experiment evaluation","实验评估"],measure_completed_actions:["Action measurement","行动结果测量"],import_search_console:["Search Console import","Search Console 数据导入"],sync_website_health:["Six-site health check","六网站健康检查"],import_website_analytics:["Six-site traffic import","六网站访问数据导入"]};return names[job.type]?.[locale==="zh"?1:0]??job.type.replaceAll("_"," ");}
function auditActionName(action){const names={sync_six_site_website_analytics:["Six-site traffic sync","六网站访问数据同步"],sync_six_website_health:["Six-site health sync","六网站健康同步"],verify_and_register_app_store_launch:["App Store launch verification","App Store 上线验证"],prepare_six_site_ga4_provider:["GA4 provider preparation","GA4 数据源准备"],register_six_website_operations_scope:["Six-site operations registration","六网站运营范围登记"],refresh_daily_brief_from_verified_state:["Verified daily brief refresh","已验证每日简报更新"],run_growth_data_cycle_v2:["Growth data cycle V2","增长数据周期 V2"],create_ongoing_analytics_report_request:["Analytics report request creation","Analytics 报告请求创建"],initialize_growth_data_spine:["Growth data spine initialization","增长数据主干初始化"],run_style_atlas_coo_cycle:["Style Atlas COO cycle","Style Atlas COO 周期"],publish_x_image_post:["X image post publication","X 图片内容发布"],bootstrap_phase_1:["Phase 1 bootstrap","Phase 1 初始化"]};return names[action]?.[locale==="zh"?1:0]??action.replaceAll("_"," ");}
const appName=(id)=>pick(state.apps.find((app)=>app.id===id),"name")??(locale==="zh"?"产品组合":"Portfolio");
const statusClass=(status)=>["active","completed","published","available","verified_no_reviews","fresh","healthy","configured","live","success","succeeded","ready","positive","complete","verified"].includes(status)?"good":["blocked","rejected","killed","failed","stale","delayed","not_connected","negative","phase_gated"].includes(status)?"warn":"";
const tag=(status,label)=>`<span class="tag ${statusClass(status)}">${esc(label??t(status==="not_connected"?"not_connected_status":status))}</span>`;

function applyLocale(){document.documentElement.lang=locale==="zh"?"zh-CN":"en";document.querySelectorAll("[data-i18n]").forEach((el)=>el.textContent=t(el.dataset.i18n));document.querySelectorAll("[data-locale]").forEach((button)=>button.classList.toggle("active",button.dataset.locale===locale));const checkpoint=document.querySelector("[data-status-updated]");if(checkpoint&&state)checkpoint.textContent=date(state.metadata.last_updated);}
async function api(path,options){const routes={"/api/state":"./data/state.json","/api/brief":"./data/brief.json","/api/feedback-analysis":"./data/feedback-analysis.json","/api/data-health":"./data/data-health.json"};if(staticMode&&options)throw new Error(t("local_only"));const target=staticMode?routes[path]:path;if(!target)throw new Error(t("local_only"));const response=await fetch(target,options&&{...options,headers:{"content-type":"application/json","x-actor":"WonderElian",...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.error||"Request failed");return data;}
async function refresh(){[state,brief,feedbackAnalysis,dataHealth]=await Promise.all([api("/api/state"),api("/api/brief"),api("/api/feedback-analysis"),api("/api/data-health")]);render();}
const head=(key,detail)=>`<header class="page-head"><div><span class="section-no">${String(document.querySelector(`[data-view="${view}"]`)?.dataset.index??1).padStart(2,"0")}</span><h2>${t(key)}</h2></div><p>${detail}</p></header>`;

function metricCard(name){const item=brief.kpis[name];const aliases=name==="conversion_rate"?["conversion_rate","average_conversion_rate"]:[name];const rows=state.metrics.filter((row)=>aliases.includes(row.metric??row.name)&&row.value!==null).sort((a,b)=>String(b.period_end).localeCompare(String(a.period_end))).slice(0,5);return `<article class="metric-card"><span class="label">${t(`kpi_${name}`)}</span><strong>${fmt(item.value,name==="conversion_rate"?"percent":null)}</strong><small>${item.apps_reporting}/${item.apps_total} ${t("reporting")}</small><details><summary>${t("source_details")}</summary>${rows.length?rows.map((row)=>`<p><b>${esc(appName(row.app_id))}</b> · ${esc(row.source)}<br><small>${row.period_start}—${row.period_end} · ${esc(row.verification_type??"manual_verified")} · ${esc(row.source_reference)}</small></p>`).join(""):`<p>—</p>`}</details></article>`;}
function decisionCard(item,index){const c=item.decision_score?.contributions??{};return `<article class="decision-card"><div class="decision-rank">0${index+1}</div><div><span class="label">${esc(locale==="zh"?item.app_zh:item.app)} · ${t("risk_level")} ${item.risk_level}</span><h3>${esc(pick(item,"action"))}</h3><p>${esc(pick(item,"observation"))}</p><dl class="decision-evidence"><div><dt>${t("evidence")}</dt><dd>${esc(pick(item,"evidence"))}</dd></div><div><dt>${t("expected_impact")}</dt><dd>${esc(pick(item,"expected_impact"))}</dd></div></dl><details><summary>${t("why_ranked")}</summary><div class="score-grid">${Object.entries(c).map(([key,value])=>`<span>${esc(t(key))}<b>${value}</b></span>`).join("")}</div></details></div><div class="score"><small>${t("score")}</small><b>${item.priority}</b></div></article>`;}
function healthCard(item){const app=state.apps.find((row)=>row.id===item.app_id);return `<article class="health-card"><div class="health-score">${item.coverage_score}<small>/100</small></div><div><h3>${esc(pick(app,"name"))}</h3><p>${item.providers.length} ${t("providers")} · ${t("last_import")} ${date(item.last_successful_import)}</p><p>${item.missing_critical_metrics.length?`${t("missing")}: ${item.missing_critical_metrics.map((x)=>t(`kpi_${x}`)).join(", ")}`:`${t("data_coverage")}: ${item.coverage_score}%`}</p><small>${t("attribution")}: ${fmt(item.attribution.link_coverage,"percent")} links · ${fmt(item.attribution.outcome_coverage,"percent")} ${t("outcome_coverage")}</small></div></article>`;}
function freshnessCards(){const ids=["app_store_connect_api","google_search_console_api","app_store_reviews_api"];return ids.map((id)=>{const p=state.providers.find((row)=>row.id===id);return `<article class="panel"><span class="label">${esc(p?.name??id)}</span><h3>${p?tag(p.freshness??p.status):"—"}</h3><p>${t("data_through")}: <b>${esc(p?.data_through??"—")}</b></p>${p?.error?`<small class="warning">${esc(p.error)}</small>`:""}</article>`;}).join("");}
function growthScorecard(){const search=(state.search_observations??[]),attributions=state.attributions??[],reviews=(state.feedback??[]).filter((row)=>row.provider==="app_store_reviews_api"),websites=state.websites??[];const maturity=state.instrumentation?.find((row)=>row.app_id==="style-atlas")?.level??0;const direct=attributions.filter((row)=>row.confidence_class==="direct").length;const liveSites=websites.filter((row)=>row.health_status==="live").length,analyticsSites=websites.filter((row)=>row.analytics_status==="connected").length;return `<section class="card-grid growth-grid"><article class="panel"><span class="label">${t("acquisition")}</span><h3>${fmt(brief.kpis.first_time_downloads.value)}</h3><p>${t("data_through")}: ${esc(state.metadata.data_through?.app_store??state.metadata.data_through?.manual_app_store??"—")}</p></article><article class="panel"><span class="label">${t("organic_search")}</span><h3>${search.length}</h3><p>${search.length?`${fmt(search.reduce((sum,row)=>sum+(row.clicks??0),0))} clicks · ${fmt(search.reduce((sum,row)=>sum+(row.impressions??0),0))} impressions`:t("no_search_data")}</p></article><article class="panel"><span class="label">${t("content_attribution")}</span><h3>${direct}/${attributions.length}</h3><p>direct / tracked paths</p></article><article class="panel"><span class="label">${t("voice_customer")}</span><h3>${reviews.length}</h3><p>${reviews.length?`${reviews.filter((row)=>row.sentiment==="negative").length} negative`:`${t("no_feedback")}`}</p></article><article class="panel"><span class="label">${t("website_health")}</span><h3>${liveSites}/${websites.length}</h3><p>${t("analytics_connected")}: ${analyticsSites}/${websites.length}</p></article><article class="panel"><span class="label">${t("instrumentation")}</span><h3>${t("maturity")} ${maturity}/5</h3><p>Style Atlas</p></article></section>`;}

function phaseGate(){const analytics=state.providers.find((row)=>row.id==="app_store_connect_api");const acquisitionReady=analytics?.status==="live"&&Boolean(state.metadata.data_through?.app_store);const reconciled=(state.reconciliations??[]).length>0||(state.cycles??[]).some((cycle)=>cycle.data_through?.app_store&&(cycle.stages?.reconcile?.received??0)>0);const providerCycle=(state.cycles??[]).some((cycle)=>cycle.version==="v2"&&cycle.data_through?.app_store&&(cycle.stages?.sync?.succeeded??0)>0&&(cycle.stages?.reconcile?.received??0)>0);const ready=acquisitionReady&&reconciled&&providerCycle;return `<section class="phase-gate ${ready?"ready":"waiting"}"><div class="gate-label"><i class="ph ph-target" aria-hidden="true"></i><strong>${t("phase4_gate")}</strong></div><div class="gate-state"><b>Phase 4</b><span>${t(ready?"gate_met":"gate_unmet")}</span></div><p>${ready?t("gate_met"):t("gate_waiting_detail")}</p></section>`;}

function coverageText(count,total){return `${t("coverage")} ${count}/${total}`;}
function telemetryValue(value,count,total){return `<strong>${fmt(value)}</strong><small>${coverageText(count,total)}</small>`;}
function changeLabel(item){return pick(item,"label")??item.metric??"—";}
function changeCard(item){if(item.type==="operational_change")return `<article class="panel"><span class="label">${esc(appName(item.app_id))}</span><h3>${esc(changeLabel(item))}</h3><p>${esc(pick(item,"evidence"))}</p>${tag(item.severity)}</article>`;return `<article class="panel"><h3>${esc(item.metric)}</h3><p>${esc(item.previous_baseline)} → ${esc(item.current_value)} · ${esc(item.percentage_change)}%</p>${tag(item.severity)}</article>`;}
function dailyPortfolio(){const summary=brief.daily_portfolio??{available_dates:[],days:[],latest_verified_acquisition:{totals:{},apps_reporting:{},apps_total:state.apps.length}},dates=summary.available_dates??[];if(!dates.includes(dailyDate))dailyDate=summary.latest_date??dates.at(-1)??null;const current=summary.days.find((item)=>item.date===dailyDate)??null,siteRows=current?.websites??[],appRows=current?.apps??[],baseline=summary.latest_verified_acquisition??{totals:{},apps_reporting:{},apps_total:state.apps.length};const kpis=[
    ["website_uv",current?.website_totals.active_users,current?.website_coverage.active_users,current?.websites_total],
    ["website_pv",current?.website_totals.page_views,current?.website_coverage.page_views,current?.websites_total],
    ["daily_sessions",current?.website_totals.sessions,current?.website_coverage.sessions,current?.websites_total],
    ["daily_cta",current?.website_totals.cta_clicks,current?.website_coverage.cta_clicks,current?.websites_total],
    ["app_dau",current?.app_totals.active_users,current?.app_coverage.active_users,current?.apps_total],
    ["daily_downloads",current?.app_totals.first_time_downloads,current?.app_coverage.first_time_downloads,current?.apps_total],
  ];const appById=new Map(appRows.map((row)=>[row.app_id,row])),websiteById=new Map(siteRows.map((row)=>[row.website_id,row]));const period=baseline.period_start&&baseline.period_end?`${baseline.period_start} — ${baseline.period_end}`:"—";return `<section class="section-block daily-portfolio"><div class="section-title telemetry-title"><span>01</span><h3>${t("daily_portfolio")}</h3><label><span>${t("latest_complete_day")}</span><select data-daily-date ${dates.length?"":"disabled"}>${dates.length?dates.slice().reverse().map((item)=>`<option value="${esc(item)}" ${item===dailyDate?"selected":""}>${esc(item)}</option>`).join(""):`<option>—</option>`}</select></label></div>${current?`<div class="telemetry-rack">${kpis.map(([key,value,count,total])=>`<article><span>${t(key)}</span>${telemetryValue(value,count??0,total??0)}</article>`).join("")}</div><p class="telemetry-note"><i class="ph ph-info" aria-hidden="true"></i>${t("uv_note")}</p><div class="portfolio-ledgers"><article class="telemetry-ledger"><header><div><span class="label">APP PORTFOLIO</span><h4>${t("apps_and_h5")}</h4></div><b>${state.apps.length}</b></header><div class="telemetry-table-wrap"><table class="telemetry-table"><thead><tr><th>${t("apps")}</th><th>${t("h5_uv")}</th><th>${t("h5_pv")}</th><th>${t("daily_sessions")}</th><th>${t("app_dau")}</th><th>${t("daily_downloads")}</th></tr></thead><tbody>${state.apps.map((app)=>{const row=appById.get(app.id)??{website_ids:[],h5_metrics:{},app_metrics:{}};return `<tr><th><strong>${esc(pick(app,"name"))}</strong><small>${row.website_ids.length} ${t("linked_sites")}</small></th><td>${fmt(row.h5_metrics.active_users)}</td><td>${fmt(row.h5_metrics.page_views)}</td><td>${fmt(row.h5_metrics.sessions)}</td><td>${fmt(row.app_metrics.active_users)}</td><td>${fmt(row.app_metrics.first_time_downloads)}</td></tr>`;}).join("")}</tbody></table></div></article><article class="telemetry-ledger"><header><div><span class="label">WEB PORTFOLIO</span><h4>${t("website_breakdown")}</h4></div><b>${state.websites.length}</b></header><div class="telemetry-table-wrap"><table class="telemetry-table"><thead><tr><th>${t("websites")}</th><th>UV</th><th>PV</th><th>${t("daily_sessions")}</th><th>${t("daily_cta")}</th><th>${t("analytics_state")}</th></tr></thead><tbody>${state.websites.map((site)=>{const row=websiteById.get(site.id)??{metrics:{}};return `<tr><th><strong>${esc(pick(site,"name"))}</strong><small>${esc(new URL(site.url).hostname)}</small></th><td>${fmt(row.metrics.active_users)}</td><td>${fmt(row.metrics.page_views)}</td><td>${fmt(row.metrics.sessions)}</td><td>${fmt(row.metrics.cta_clicks)}</td><td>${tag(site.analytics_status)}</td></tr>`;}).join("")}</tbody></table></div></article></div>`:`<article class="empty-state"><strong>${t("no_daily_data")}</strong></article>`}<article class="acquisition-baseline"><div><span class="label">APP STORE</span><h4>${t("app_store_latest_verified")}</h4><small>${period} · ${esc(baseline.verification_type??"—")}</small></div><dl><div><dt>${t("daily_downloads")}</dt><dd>${fmt(baseline.totals.first_time_downloads)}</dd></div><div><dt>${t("app_product_views")}</dt><dd>${fmt(baseline.totals.product_page_views)}</dd></div><div><dt>${t("impressions")}</dt><dd>${fmt(baseline.totals.impressions)}</dd></div><div><dt>${t("coverage")}</dt><dd>${baseline.apps_reporting.first_time_downloads??0}/${baseline.apps_total??state.apps.length}</dd></div></dl></article><p class="telemetry-note"><i class="ph ph-shield-check" aria-hidden="true"></i>${t("app_daily_note")}</p></section>`;}

function dailyOperations(){const operatingDay=latestOperatingDay();const dailyAudits=state.audit.filter((item)=>day(item.at)===operatingDay),verified=dailyAudits.filter((item)=>["success","succeeded","completed"].includes(item.status)),published=state.content.filter(publishedWithEvidence),dailyContent=published.filter((item)=>day(item.published_at)===operatingDay),channels=new Map();for(const item of published)channels.set(item.channel_id,(channels.get(item.channel_id)??0)+1);const quickJobs=state.jobs.slice().sort((a,b)=>String(b.last_run??"").localeCompare(String(a.last_run??"")));return `<section class="section-block daily-operations"><div class="section-title operations-title"><span>02</span><h3>${t("daily_operations")}</h3><div><small>${t("operations_day")}</small><strong>${esc(operatingDay)}</strong><button class="text-button" data-open-view="activity">${t("view_operations_log")} <i class="ph ph-arrow-right" aria-hidden="true"></i></button></div></div><div class="operation-stats"><article><strong>${state.jobs.length}</strong><span>${t("scheduled_tasks")}</span></article><article><strong>${verified.length}</strong><span>${t("verified_outcomes")}</span></article><article><strong>${dailyContent.length}</strong><span>${t("published_today")}</span></article><article><strong>${published.length}</strong><span>${t("permanent_urls")}</span></article></div><div class="operations-rack"><article class="operation-panel"><header><span class="label">01 / PLAN</span><h4>${t("scheduled_tasks")}</h4></header><div class="operation-timeline">${quickJobs.map((job)=>`<div class="operation-row"><time>${job.last_run?date(job.last_run):"—"}</time><div><strong>${esc(jobName(job))}</strong><small>${esc(job.schedule)} · ${t("next_run")} ${date(job.next_run)}</small></div>${tag(job.status)}</div>`).join("")}</div></article><article class="operation-panel"><header><span class="label">02 / PROOF</span><h4>${t("verified_outcomes")}</h4></header><div class="operation-timeline">${dailyAudits.length?dailyAudits.map((item)=>`<div class="operation-row evidence"><time>${date(item.at)}</time><div><strong>${esc(auditActionName(item.action))}</strong><small>${esc(item.source)} · ${esc(resultSummary(item.result)=== "—"?t("verified_record"):resultSummary(item.result))}</small></div>${tag(item.status)}</div>`).join(""):`<p class="empty">${t("no_outcomes_today")}</p>`}</div></article><article class="operation-panel"><header><span class="label">03 / DISTRIBUTION</span><h4>${t("content_distribution")}</h4></header><div class="distribution-ledger">${dailyContent.length?dailyContent.map((item)=>{const path=attributionCompleteness(item);return `<a class="distribution-item" href="${esc(permanentContentUrl(item))}" target="_blank" rel="noreferrer"><span>${esc(channelName(item.channel_id))}</span><strong>${esc(pick(item,"title"))}</strong><small>${t("attribution_path")} ${path.complete}/${path.total}</small></a>`;}).join(""):`<p class="empty">${t("no_publications_today")}</p>`}<div class="channel-summary">${[...channels].map(([id,count])=>`<span>${esc(channelName(id))}<b>${count}</b></span>`).join("")}</div></div></article></div></section>`;}

function command(){const executions=state.executions??[],outcomes=state.action_outcomes??[];const counters={pending:state.actions.filter((a)=>a.status==="proposed"&&a.approval_required).length,executing:executions.filter((x)=>x.state==="executing").length,awaiting:outcomes.filter((x)=>x.result==="inconclusive").length,proven:outcomes.filter((x)=>["positive","negative","neutral"].includes(x.result)).length,failed:executions.filter((x)=>x.state==="failed").length};return `${head("daily_brief",`${t("updated")} ${date(state.metadata.last_updated)}`)}
  <section class="command-hero"><div><span class="label">${t("daily_brief")}</span><h3>${day(state.metadata.last_updated)}</h3><p>${esc(locale==="zh"?brief.portfolio_summary_zh:brief.portfolio_summary)}</p></div><div class="signal"><span>${t("what_changed")}</span><strong>${brief.no_material_change?"0":brief.what_changed.length}</strong><small>${brief.no_material_change?t("no_material_change"):brief.what_changed.map(changeLabel).join(", ")}</small></div></section>
  ${dailyPortfolio()}
  ${dailyOperations()}
  ${phaseGate()}
  <section class="section-block"><div class="section-title"><span>03</span><h3>${t("todays_decisions")}</h3></div><div class="decision-stack">${brief.decisions.map(decisionCard).join("")}</div></section>
  <section class="split"><div class="section-block"><div class="section-title"><span>04</span><h3>${t("what_changed")}</h3></div>${brief.no_material_change?`<article class="empty-state"><strong>${t("no_material_change")}</strong><p>${t("no_material_detail")}</p></article>`:brief.what_changed.map(changeCard).join("")}</div>
  <div class="section-block"><div class="section-title"><span>05</span><h3>${t("data_freshness")}</h3></div><div class="card-grid freshness-grid">${freshnessCards()}</div></div></section>
  <section class="section-block"><div class="section-title"><span>06</span><h3>${t("north_star")}</h3></div><section class="metric-strip">${["first_time_downloads","conversion_rate","content_published","revenue"].map(metricCard).join("")}</section></section>
  <section class="section-block"><div class="section-title"><span>07</span><h3>${t("growth_scorecard")}</h3></div>${growthScorecard()}</section>
  <section class="section-block"><div class="section-title"><span>08</span><h3>${t("execution_measurement")}</h3></div><div class="execution-grid">${Object.entries(counters).map(([key,value])=>`<article><strong>${value}</strong><span>${t(key==="pending"?"pending_approvals":key==="awaiting"?"awaiting_results":key)}</span></article>`).join("")}</div></section>
  <section class="section-block"><div class="section-title"><span>09</span><h3>${t("portfolio_health")}</h3></div><div class="health-grid">${dataHealth.map(healthCard).join("")}</div></section>`;}

function appsView(){return `${head("apps",t("apps_detail"))}<section class="card-grid">${state.apps.map((app)=>{const metrics=state.metrics.filter((m)=>m.app_id===app.id);return `<article class="panel app-card"><span class="label">${esc(app.id)}</span><h3>${esc(pick(app,"name"))}</h3><p>${(app.platforms??[]).map((p)=>tag("",p)).join("")} ${tag(app.status)}</p><div class="app-links"><a href="${esc(app.website_url)}" target="_blank" rel="noreferrer">${t("website_link")}</a>${app.app_store_url?`<a href="${esc(app.app_store_url)}" target="_blank" rel="noreferrer">${t("app_store_link")}</a>`:""}</div><div class="mini-list"><strong>${t("latest_metrics")}</strong>${metrics.length?metrics.map((m)=>`<p><b>${esc(m.metric)}</b> ${fmt(m.value,m.unit)}<small>${esc(m.source)} · ${tag(m.freshness)} · ${m.period_start}—${m.period_end}</small></p>`).join(""):`<p>—</p>`}</div></article>`;}).join("")}</section>`;}
function insightsView(){return `${head("insights",t("insights_detail"))}<section class="stack">${state.insights.map((item)=>`<article class="panel insight"><div><span class="label">${esc(appName(item.app_id))}</span><h3>${esc(pick(item,"observation"))}</h3><dl class="decision-evidence"><div><dt>${t("evidence")}</dt><dd>${esc(pick(item,"evidence"))}</dd></div><div><dt>${t("interpretation")}</dt><dd>${esc(pick(item,"interpretation")??pick(item,"reason"))}</dd></div><div><dt>${t("recommendation")}</dt><dd>${esc(pick(item,"recommended_action"))}</dd></div></dl><button data-create-action="${item.id}">${t("propose_action")}</button></div></article>`).join("")}</section>`;}
function actionRow(action){const execution=state.executions.find((x)=>x.action_id===action.id);const next=action.status==="proposed"?["approved","rejected"]:action.status==="approved"?["executing","rejected"]:action.status==="executing"&&action.risk_level<2?["completed"]:[];return `<article class="panel action-row"><div><span class="label">${esc(appName(action.app_id))} · ${t("risk_level")} ${action.risk_level??2}</span><h3>${esc(pick(action,"title"))}</h3><p>${tag(action.status)} ${execution?tag(execution.state):""} · ${t("approval")}: ${action.approval_required?t("required"):t("not_required")}</p><div class="actions">${next.map((status)=>`<button data-transition-action="${action.id}" data-status="${status}" data-risk="${action.risk_level??2}">${t(status)}</button>`).join("")}</div></div><div class="score"><small>${t("score")}</small><b>${action.priority??"—"}</b></div></article>`;}
function actionsView(){return `${head("actions",t("actions_detail"))}<section class="section-block"><div class="section-title"><span>01</span><h3>${t("execution_queue")}</h3></div><div class="stack">${state.actions.map(actionRow).join("")}</div></section><section class="section-block"><div class="section-title"><span>02</span><h3>${t("outcomes")}</h3></div><div class="card-grid">${state.action_outcomes.map((o)=>`<article class="panel"><span class="label">${esc(o.action_id)}</span><h3>${esc(o.observed_effect)}</h3>${tag(o.result)}<p>${esc(o.metric??"—")}: ${fmt(o.metric_before)} → ${fmt(o.metric_after)}</p></article>`).join("")}</div></section>`;}
function experimentsView(){return `${head("experiments",t("experiments_detail"))}<section class="card-grid">${state.experiments.map((item)=>`<article class="panel"><span class="label">${esc(appName(item.app_id))}</span><h3>${esc(pick(item,"name"))}</h3><p>${esc(pick(item,"hypothesis"))}</p>${tag(item.status)}<dl class="decision-evidence"><div><dt>${t("primary")}</dt><dd>${esc(item.primary_metric)}</dd></div><div><dt>${t("sample_requirement")}</dt><dd>${esc(item.sample_requirement)}</dd></div><div><dt>${t("current_result")}</dt><dd>${item.current_result===null?t(item.result_status):esc(item.current_result)}</dd></div></dl>${(item.urls??[]).map((url)=>`<a class="block-link" href="${esc(url)}" target="_blank" rel="noreferrer">${esc(url)}</a>`).join("")}</article>`).join("")}</section>`;}
function contentView(){const geo=state.geo_observations??[];return `${head("content",t("content_detail"))}<section class="section-block"><div class="section-title"><span>01</span><h3>${t("geo_readiness")}</h3></div><section class="card-grid">${geo.map((item)=>`<article class="panel"><span class="label">${esc(item.dimension)}</span><h3>${tag(item.status)}</h3><a href="${esc(item.page)}" target="_blank" rel="noreferrer">${esc(item.page)}</a><p>${esc(item.evidence)}</p><small>Search: ${esc(item.search_performance_status??"unknown")} · AI citation: ${esc(item.ai_citation_status??"unknown")}</small></article>`).join("")}</section></section><section class="section-block"><div class="section-title"><span>02</span><h3>${t("content_attribution")}</h3></div><section class="stack">${state.content.map((item)=>`<article class="panel content-row"><div><span class="label">${esc(item.channel_id)} / ${esc(item.type)}</span><h3>${esc(pick(item,"title"))}</h3><a href="${esc(item.publish_url??item.url)}" target="_blank" rel="noreferrer">${esc(item.publish_url??item.url)}</a><p>${tag(item.status)} ${tag(item.measurement_status)} <span class="tag">${t("downloads")} ${fmt(item.first_time_downloads)}</span></p></div><dl><div><dt>${t("campaign")}</dt><dd>${esc(item.campaign_id)}</dd></div><div><dt>${t("landing")}</dt><dd>${esc(item.landing_url)}</dd></div><div><dt>${t("measurement_status")}</dt><dd>${esc(t(item.measurement_status))}</dd></div></dl></article>`).join("")}</section></section>`;}
function latestWebsiteObservation(websiteId){return (state.website_observations??[]).filter((row)=>row.website_id===websiteId).sort((a,b)=>String(b.observed_at).localeCompare(String(a.observed_at)))[0]??null;}
function websiteMetric(websiteId,name){const row=(state.website_metrics??[]).filter((item)=>item.website_id===websiteId&&(item.metric??item.name)===name&&item.value!==null).sort((a,b)=>String(b.period_end).localeCompare(String(a.period_end)))[0];return row?.value??null;}
function websiteReadiness(observation){if(!observation)return{score:0,total:7};const checks=[observation.description,observation.canonical,observation.h1,observation.og_title,observation.structured_data_count>0,observation.robots_valid,observation.sitemap_valid];return{score:checks.filter(Boolean).length,total:checks.length};}
function websitesView(){const websites=state.websites??[],operations=state.website_operations??[],live=websites.filter((site)=>site.health_status==="live").length,tagged=websites.filter((site)=>["tag_detected","connected"].includes(site.analytics_status)).length,connected=websites.filter((site)=>site.analytics_status==="connected").length,analyticsProvider=state.providers.find((row)=>row.id==="website_analytics_api");return `${head("websites",t("websites_detail"))}<section class="command-hero"><div><span class="label">${t("sites_tracked")}</span><h3>${websites.length}</h3><p>${t("data_through")}: ${esc(state.metadata.data_through?.website_health??"—")}</p></div><div class="signal"><span>${t("sites_live")}</span><strong>${live}/${websites.length}</strong><small>${t("analytics_tag")}: ${tagged}/${websites.length} · ${t("analytics_connected")}: ${connected}/${websites.length}</small></div></section><section class="section-block"><div class="section-title"><span>01</span><h3>${t("traffic_metrics")}</h3></div><p class="warning">${esc(analyticsProvider?.error??"—")}</p><section class="card-grid">${websites.map((site)=>{const observation=latestWebsiteObservation(site.id),readiness=websiteReadiness(observation);return `<article class="panel website-card"><span class="label">${esc(site.kind)} · ${esc(site.hosting)}</span><h3>${esc(pick(site,"name"))}</h3><a href="${esc(site.url)}" target="_blank" rel="noreferrer">${esc(site.url)}</a><p>${tag(site.health_status)} ${tag(site.analytics_status)}</p><div class="score-grid"><span>HTTP<b>${fmt(observation?.http_status)}</b></span><span>${t("technical_readiness")}<b>${readiness.score}/${readiness.total}</b></span><span>${t("page_views")}<b>${fmt(websiteMetric(site.id,"page_views"))}</b></span><span>${t("sessions")}<b>${fmt(websiteMetric(site.id,"sessions"))}</b></span><span>${t("cta_clicks")}<b>${fmt(websiteMetric(site.id,"cta_clicks"))}</b></span></div><small>${t("primary_conversion")}: ${esc(site.primary_conversion)}<br>${t("last_checked")}: ${date(site.last_checked_at)}</small></article>`;}).join("")}</section></section><section class="section-block"><div class="section-title"><span>02</span><h3>${t("operating_queue")}</h3></div><section class="stack">${operations.sort((a,b)=>String(a.priority).localeCompare(String(b.priority))).map((item)=>{const site=websites.find((row)=>row.id===item.website_id);return `<article class="panel content-row"><div><span class="label">${esc(item.priority)} · ${esc(pick(site,"name"))}</span><h3>${esc(pick(item,"title"))}</h3><p>${esc(pick(item,"next_action"))}</p></div><div>${tag(item.status)}</div></article>`;}).join("")}</section></section>`;}
function customersView(){const reviewProvider=state.providers.find((row)=>row.id==="app_store_reviews_api");return `${head("customers",t("customers_detail"))}<section class="command-hero"><div><span class="label">App Store Reviews API</span><h3>${tag(reviewProvider?.status??"not_connected")}</h3><p>${esc(reviewProvider?.error??`${t("data_through")}: ${reviewProvider?.data_through??"—"}`)}</p></div><div class="signal"><span>${t("customer_feedback")}</span><strong>${state.feedback.length}</strong><small>${t("data_through")}: ${esc(reviewProvider?.data_through??"—")}</small></div></section><section class="split"><article class="panel"><h3>${t("customer_feedback")}</h3>${state.feedback.length?state.feedback.map((item)=>`<p><strong>${item.rating?`${item.rating}/5 · `:""}${esc(item.title??item.text)}</strong><small>${esc(item.source)} · ${esc(item.topic??"unclassified")} · ${esc(item.territory??"—")}</small></p>`).join(""):`<p class="empty">${t("no_feedback")}</p>`}</article><article class="panel"><h3>${t("detected_opportunities")}</h3>${feedbackAnalysis.opportunities.length?feedbackAnalysis.opportunities.map((o)=>`<p>${esc(o.problem)} · ${o.frequency}</p>`).join(""):`<p class="empty">${t("opportunity_empty")}</p>`}</article></section>`;}
function sourcesView(){const syncs=(state.provider_syncs??[]).slice().reverse().slice(0,12);const authLabel=(p)=>p.authentication_status==="configured"?t("configured"):p.authentication_status==="not_required"?t("not_required"):p.authentication_required?t("auth_required"):t("not_required");return `${head("data_sources",t("data_sources_detail"))}<section class="provider-table"><div class="table-head"><span>${t("providers")}</span><span>${t("status")}</span><span>${t("data_through")}</span><span>${t("data_available")}</span><span>${t("authentication")}</span></div>${state.providers.map((p)=>`<article><div><strong>${esc(p.name)}</strong><small>${esc((p.app_ids??[]).map(appName).join(", "))}</small></div><div>${tag(p.status)} ${p.freshness?tag(p.freshness):""}</div><div>${esc(p.data_through??"—")}</div><div>${(p.data_available??[]).length?(p.data_available??[]).map((x)=>tag("",x)).join(""):"—"}</div><div>${authLabel(p)}${p.error?`<small class="warning">${esc(p.error)}</small>`:""}</div></article>`).join("")}</section><section class="section-block"><div class="section-title"><span>02</span><h3>${t("instrumentation")}</h3></div><section class="card-grid">${(state.instrumentation??[]).map((item)=>`<article class="panel"><span class="label">${esc(appName(item.app_id))}</span><h3>${t("maturity")} ${item.level}/5</h3><p>${esc(item.source)}</p></article>`).join("")}</section></section><section class="section-block"><div class="section-title"><span>03</span><h3>${t("sync_history")}</h3><button data-run-cycle>${t("run_cycle")}</button></div><p class="cycle-status" role="status"></p><section class="card-grid jobs">${syncs.length?syncs.map((sync)=>`<article class="panel"><span class="label">${esc(sync.provider)}</span><h3>${tag(sync.status)}</h3><p>${sync.records_received} received · ${sync.records_inserted} inserted · ${sync.records_updated??0} updated</p><small>${sync.period_start??"—"}—${sync.period_end??"—"}<br>${t("data_through")}: ${sync.data_through??"—"}</small>${sync.error?`<p class="warning">${esc(sync.error.message)}</p>`:""}</article>`).join(""):`<p class="empty">—</p>`}</section></section><section class="section-block"><div class="section-title"><span>04</span><h3>${t("jobs")}</h3></div><section class="card-grid jobs">${state.jobs.map((job)=>`<article class="panel"><span class="label">${esc(job.type)}</span><h3>${esc(job.provider)}</h3><p>${tag(job.status)}</p><small>${t("last_run")}: ${date(job.last_run)}<br>${t("next_run")}: ${date(job.next_run)}<br>${t("retry_count")}: ${job.retry_count}</small>${job.error?`<p class="warning">${esc(job.error)}</p>`:""}</article>`).join("")}</section></section>`;}
function playbooksView(){const system=brief.marketing_playbooks??{summary:{total:0,ready:0,waiting_evidence:0,phase_gated:0},playbooks:[],source:{},policy:{}};return `${head("playbooks",t("playbooks_detail"))}<section class="command-hero playbook-summary"><div><span class="label">${t("methods_ready")}</span><h3>${system.summary.ready}/${system.summary.total}</h3><p>${t("waiting_evidence_count")}: ${system.summary.waiting_evidence} · ${t("phase_gated_count")}: ${system.summary.phase_gated}</p></div><div class="signal"><span>${t("integration_policy")}</span><strong>${system.policy.external_execution==="disabled"?"OFF":"ON"}</strong><small>${t("external_execution_disabled")}</small></div></section><section class="source-notice"><div><span class="label">${t("source_framework")}</span><a href="${esc(system.source.commit_url)}" target="_blank" rel="noreferrer">${esc(system.source.name)} @ ${esc(String(system.source.commit??"").slice(0,7))}</a></div><p>${t("adapted_not_vendored")} · ${esc(system.source.license)}</p></section><section class="section-block"><div class="section-title"><span>01</span><h3>${t("playbooks")}</h3></div><section class="card-grid playbook-grid">${system.playbooks.map((item)=>`<article class="panel playbook-card" data-readiness="${esc(item.status)}"><div class="playbook-card-head"><span class="label">${esc(item.category)} · ${String(item.priority).padStart(2,"0")}</span>${tag(item.status)}</div><h3>${esc(pick(item,"name"))}</h3><p>${esc(pick(item,"outcome"))}</p><div class="requirement-list"><span class="label">${t("requirements")}</span>${item.requirements.map((requirement)=>`<div class="requirement ${requirement.met?"met":"missing"}"><i class="ph ${requirement.met?"ph-check-circle":"ph-circle-dashed"}" aria-hidden="true"></i><span>${esc(pick(requirement,"label"))}</span></div>`).join("")}</div><dl class="playbook-guidance"><div><dt>${t("next_internal_action")}</dt><dd>${esc(pick(item,"next_action"))}</dd></div><div><dt>${t("guardrail")}</dt><dd>${esc(pick(item,"guardrail"))}</dd></div></dl></article>`).join("")}</section></section>`;}
function jobRow(job){return `<tr><th><strong>${esc(jobName(job))}</strong><small>${esc(job.provider)}</small></th><td>${esc(job.schedule)}</td><td>${date(job.last_run)}</td><td>${date(job.next_run)}</td><td>${tag(job.status)}</td><td>${esc(resultSummary(job.result))}${job.error?`<small class="warning">${esc(job.error)}</small>`:""}</td></tr>`;}
function auditRow(item){return `<div class="audit-row"><div><strong>${esc(auditActionName(item.action))}</strong><p>${esc(resultSummary(item.result)=== "—"?t("verified_record"):resultSummary(item.result))}</p><small>${date(item.at)} · ${esc(item.actor)} · ${esc(item.source)}</small></div>${tag(item.status)}</div>`;}
function contentDistributionRow(item){const path=attributionCompleteness(item),url=permanentContentUrl(item);return `<tr><th><strong>${esc(pick(item,"title"))}</strong><small>${esc(item.type)} · ${esc(item.id)}</small></th><td>${esc(channelName(item.channel_id))}</td><td>${esc(item.published_at??"—")}</td><td><a href="${esc(url)}" target="_blank" rel="noreferrer">${t("permanent_url")} <i class="ph ph-arrow-square-out" aria-hidden="true"></i></a></td><td><span class="path-meter"><b style="--path:${path.complete}">${path.complete}/${path.total}</b><small>${t("content_to_download")}</small></span></td><td>${fmt(item.first_time_downloads)}</td></tr>`;}
function activityView(){const operatingDay=latestOperatingDay(),published=state.content.filter(publishedWithEvidence),verified=state.audit.filter((item)=>["success","succeeded","completed"].includes(item.status)).length;return `${head("activity",`${t("operations_day")} ${operatingDay} · ${t("all_history")}`)}<section class="operation-stats log-stats"><article><strong>${state.jobs.length}</strong><span>${t("scheduled_tasks")}</span></article><article><strong>${verified}</strong><span>${t("verified_outcomes")}</span></article><article><strong>${published.length}</strong><span>${t("permanent_urls")}</span></article><article><strong>${new Set(published.map((item)=>item.channel_id)).size}</strong><span>${t("active_channels")}</span></article></section><section class="section-block"><div class="section-title"><span>01</span><h3>${t("scheduled_tasks")}</h3></div><div class="operations-table-wrap"><table class="operations-table"><thead><tr><th>${t("scheduled_tasks")}</th><th>${t("schedule")}</th><th>${t("last_run")}</th><th>${t("next_run")}</th><th>${t("status")}</th><th>${t("result")}</th></tr></thead><tbody>${state.jobs.map(jobRow).join("")}</tbody></table></div></section><section class="section-block"><div class="section-title"><span>02</span><h3>${t("verified_outcomes")}</h3></div><section class="panel audit-ledger">${state.audit.map(auditRow).join("")}</section></section><section class="section-block"><div class="section-title"><span>03</span><h3>${t("content_distribution")}</h3></div><div class="operations-table-wrap"><table class="operations-table distribution-table"><thead><tr><th>${t("content")}</th><th>${t("active_channels")}</th><th>${t("period")}</th><th>${t("permanent_url")}</th><th>${t("attribution_path")}</th><th>${t("downloads")}</th></tr></thead><tbody>${state.content.filter(publishedWithEvidence).map(contentDistributionRow).join("")}</tbody></table></div></section><section class="section-block"><div class="section-title"><span>04</span><h3>${t("operating_cycles")}</h3></div>${state.cycles.length?state.cycles.slice().reverse().map((cycle)=>`<article class="panel cycle"><div><span class="label">${esc(cycle.id)}</span><h3>${esc(cycle.detected.result)}</h3><p>${esc(cycle.decided.decision)}</p></div>${tag(cycle.status)}</article>`).join(""):`<p class="empty">—</p>`}</section>`;}

function bind(){document.querySelector("[data-daily-date]")?.addEventListener("change",(event)=>{dailyDate=event.currentTarget.value;render();});document.querySelectorAll("[data-open-view]").forEach((button)=>button.onclick=()=>{document.querySelector("nav .active")?.classList.remove("active");document.querySelector(`[data-view="${button.dataset.openView}"]`)?.classList.add("active");view=button.dataset.openView;render();});document.querySelectorAll("[data-transition-action]").forEach((button)=>button.onclick=async()=>{const payload={status:button.dataset.status};if(button.dataset.status==="approved")payload.approval_source="local_dashboard_explicit_approval";if(button.dataset.status==="completed")payload.output_identifier="internal-dashboard-completion";await api(`/api/actions/${button.dataset.transitionAction}/transition`,{method:"POST",body:JSON.stringify(payload)});await refresh();});document.querySelectorAll("[data-create-action]").forEach((button)=>button.onclick=async()=>{await api(`/api/insights/${button.dataset.createAction}/actions`,{method:"POST",body:"{}"});await refresh();});document.querySelector("[data-run-cycle]")?.addEventListener("click",async(event)=>{const status=document.querySelector(".cycle-status");event.currentTarget.disabled=true;status.textContent=t("cycle_running");try{await api("/api/cycle/run",{method:"POST",body:JSON.stringify({app_id:"style-atlas"})});status.textContent=t("cycle_done");await refresh();}catch(error){status.textContent=error.message;event.currentTarget.disabled=false;}});}
function render(){applyLocale();root.innerHTML=({command,apps:appsView,insights:insightsView,actions:actionsView,experiments:experimentsView,content:contentView,customers:customersView,sources:sourcesView,websites:websitesView,playbooks:playbooksView,activity:activityView}[view])();bind();}
document.querySelectorAll("nav button").forEach((button)=>button.onclick=()=>{document.querySelector("nav .active")?.classList.remove("active");button.classList.add("active");view=button.dataset.view;render();});
document.querySelectorAll("[data-locale]").forEach((button)=>button.onclick=()=>{locale=button.dataset.locale;localStorage.setItem("ai-coo-locale",locale);render();});
applyLocale();root.innerHTML=`<p class="loading">${t("loading")}</p>`;refresh().catch((error)=>root.innerHTML=`<p class="panel">${t("unavailable")}: ${esc(error.message)}</p>`);
